    B(C, S_, 1, 'predict', 'Hàm sau in ra gì?\n\n`fun printUntilLunch(slots: List<String>) {`\n`    slots.forEach { if (it == "12:00") return; print("$it ") }`\n`    print("hết buổi sáng")`\n`}`\n`printUntilLunch(listOf("09:00", "12:00", "14:00"))`',
      'What does this print?\n\n`fun printUntilLunch(slots: List<String>) {`\n`    slots.forEach { if (it == "12:00") return; print("$it ") }`\n`    print("morning over")`\n`}`\n`printUntilLunch(listOf("09:00", "12:00", "14:00"))`')
    B(C, S_, 1, 'ans', 'Chỉ in "09:00 ". forEach là hàm inline, nên return trần trong lambda thoát cả printUntilLunch: "14:00" không được xét và dòng "hết buổi sáng" không chạy. Đổi thành return@forEach thì in "09:00 14:00 hết buổi sáng". Mô phỏng ngay dưới đi qua cả hai. [[src:kt-returns]]',
      'Only "09:00 ". forEach is an inline function, so the bare return inside the lambda exits all of printUntilLunch: "14:00" is never looked at and "morning over" never prints. With return@forEach it prints "09:00 14:00 morning over". The simulation just below walks through both. [[src:kt-returns]]')

    S_ = 'lambda'
